from pathlib import Path
from runpy import run_path
g=run_path(str(Path(__file__).with_name('author-tools-generator.py')))
L=g['lesson']; C=g['course']

playwright=[
('A browser test','A browser test opens a page and checks what a person can do. setContent gives this test a tiny page without a website server.','await page.setContent("<h1>Library</h1>");\nawait expect(page.getByRole("heading", { name: "Library" })).toBeVisible();','The test finds a visible heading named Library.','Change the heading and the expected name.','Install Playwright and its browser with the official setup guide before running a test file.','What page does this example use?','A small page created by setContent','A real library account'),
('Find by role','A role describes what an element does. A button role and its name make a locator that resembles how a person finds the control.','await page.setContent("<button>Borrow</button>");\nawait expect(page.getByRole("button", { name: "Borrow" })).toBeVisible();','The locator finds the Borrow button.','Add a Return button and locate it by name.','A button with no useful name is hard for both people and tests to find.','Which part distinguishes this button?','The accessible name Borrow','Its position in a random list'),
('Labels identify inputs','A label tells a person what an input is for. getByLabel uses that relationship.','await page.setContent(\'<label for="title">Book title</label><input id="title">\');\nawait page.getByLabel("Book title").fill("Moon");\nawait expect(page.getByLabel("Book title")).toHaveValue("Moon");','The input receives Moon and the value check passes.','Fill Ocean instead.','Placeholder text is not a substitute for a persistent label.','What connects the label to the input?','for and id','The input color'),
('Click an action','click asks Playwright to perform a real user-like click. Check the visible result, not only that the click method returned.','await page.setContent(\'<button onclick="this.textContent=\\\"Done\\\"">Save</button>\');\nawait page.getByRole("button", { name: "Save" }).click();\nawait expect(page.getByRole("button", { name: "Done" })).toBeVisible();','After the click, the button reads Done.','Change the final word to Saved.','A successful click alone does not prove the intended action happened.','What confirms the action worked?','The changed button name','Only calling click'),
('Assertions wait for a result','Playwright locator assertions retry for a short time. This helps when a visible change happens after the action.','await page.setContent("<p>Ready</p>");\nawait expect(page.getByText("Ready", { exact: true })).toBeVisible();','The assertion checks for the exact visible text and can retry while waiting.','Try an expected word that is missing and read the failure.','Avoid fixed sleeps when you can wait for a real condition.','What is better than a guessed sleep?','Waiting for the expected condition','Waiting longer every time'),
('Count repeated items','A locator can match several elements. toHaveCount checks how many matches exist.','await page.setContent("<ul><li>Moon</li><li>Ocean</li></ul>");\nawait expect(page.getByRole("listitem")).toHaveCount(2);','The list has two items.','Add Zoo and update the expected count.','A count alone does not check the text of every item.','How many list items are expected?','2','3'),
('Check a checkbox','check sets a checkbox to checked. It is clearer than clicking when the desired state is known.','await page.setContent(\'<label><input type="checkbox">Remember this book</label>\');\nconst box = page.getByLabel("Remember this book");\nawait box.check();\nawait expect(box).toBeChecked();','The checkbox ends in the checked state.','Use uncheck and a not.toBeChecked assertion.','Clicking a box twice can return it to the original state.','Which action clearly requests the checked state?','check','Two clicks'),
('Select an option','A select input stores an option value. The label shown to people can differ from that value.','await page.setContent(\'<label>Size<select><option value="s">Small</option><option value="l">Large</option></select></label>\');\nawait page.getByLabel("Size").selectOption("l");\nawait expect(page.getByLabel("Size")).toHaveValue("l");','The Large option is selected and its value is l.','Select s and check the value.','Use selectOption for a native select, not for every custom menu.','What is Large\'s stored value?','l','Large by necessity'),
('Test keyboard access','A keyboard test checks focus and key actions. It can reveal a control that works only with a mouse.','await page.setContent("<button>First</button><button>Second</button>");\nawait page.getByRole("button", { name: "First" }).focus();\nawait page.keyboard.press("Tab");\nawait expect(page.getByRole("button", { name: "Second" })).toBeFocused();','Tab moves focus from the first button to the second.','Try Shift+Tab to move back.','Visible focus should remain easy to see on the real page.','What does Tab move here?','Keyboard focus','The button text'),
('Mock a page response','A route handler can provide a known response. The test controls the content without calling a real external service.','await page.route("https://books.test/", route => route.fulfill({ contentType: "text/html", body: "<h1>Book list</h1>" }));\nawait page.goto("https://books.test/");\nawait expect(page.getByRole("heading", { name: "Book list" })).toBeVisible();','The route handler supplies the whole page. No real books.test server is needed for this request.','Return a different heading from the handler.','Register the route before the request it must catch.','Who supplies this page?','The test route handler','A required paid service'),
('Isolate test state','Each Playwright test normally gets a fresh browser context. A context separates saved state such as cookies between tests.','await page.setContent("<p>Fresh test</p>");\nawait expect(page.getByText("Fresh test", { exact: true })).toBeVisible();','This test starts from its own page fixture. Another test should arrange its own required data.','Explain why test B should not depend on test A having clicked Save.','Do not rely on test order to create the state a test needs.','What should each test prepare?','Its own needed state','A dependency on the previous test'),
('Capture useful evidence','A screenshot records visible state. It helps explain a failure but is not a replacement for a precise behaviour check.','await page.setContent("<h1>Library</h1>");\nawait expect(page.getByRole("heading")).toHaveText("Library");\nawait page.screenshot({ path: "library.png", fullPage: true });','The test checks the heading and saves a screenshot in the local test project.','Choose a meaningful file name for a search-result screenshot.','Do not approve changed visual snapshots without looking at the changes.','What does a screenshot capture?','Visible page state','Every hidden program rule'),
]
def pw_record(row):
    title,idea,body,result,task,warning,q,a,w=row
    code='import { test, expect } from "@playwright/test";\n\ntest("'+title.lower()+'", async ({ page }) => {\n'+ '\n'.join('  '+line for line in body.splitlines())+'\n});'
    return L(title,idea,code,result,task,warning,q,a,w,language='typescript')
C('playwright','Playwright checks websites in real browsers. These lessons use tiny local page examples so you can learn locators, actions and assertions without needing an online account.','Run these TypeScript test files in a local Playwright project. The site only displays them; its normal JavaScript playground is not a browser-test runner.','https://playwright.dev/docs/intro',[pw_record(r) for r in playwright])

cypress=[
('Meet the Cypress runner','Cypress runs browser checks as a chain of commands. This example starts with a blank local practice page.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML = "<h1>Library</h1>"; });\ncy.contains("h1", "Library").should("be.visible");','The test inserts and checks a Library heading on the local page.','Change the heading to Reading club.','Serve a blank practice.html from your local frontend project and configure baseUrl first.','What page must exist locally?','practice.html','A paid account dashboard'),
('Select a clear target','A stable data attribute can identify a control without tying a test to its visual style.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML = \'<button data-cy="borrow">Borrow</button>\'; });\ncy.get(\'[data-cy="borrow"]\').should("have.text", "Borrow");','The selector finds the button by its testing attribute.','Change its CSS class without changing data-cy.','A color class is often a fragile test selector because design changes it.','Which attribute is used for this target?','data-cy','Its background color'),
('Type into a field','type enters text and clear removes existing text. A final value check confirms the input received it.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML = \'<label for="title">Title</label><input id="title">\'; });\ncy.get("#title").type("Moon").should("have.value", "Moon");','The input contains Moon.','Clear the field and type Ocean.','Cypress commands are queued; do not read their result like an immediate normal value.','What should have.value check?','The field value','The label color'),
('Click and check the effect','A click test needs an observable result. Here the button changes its own text.','cy.visit("/practice.html");\ncy.document().then(doc => { const b=doc.createElement("button"); b.textContent="Save"; b.onclick=()=>b.textContent="Done"; doc.body.replaceChildren(b); });\ncy.contains("button", "Save").click();\ncy.contains("button", "Done").should("be.visible");','The click changes Save to Done.','Make the result Saved instead.','Do not consider a click alone proof of the business result.','Which result is checked?','The Done button text','That no code exists'),
('Retry an assertion','Cypress retries many queries and assertions until they pass or time out. Check a real condition instead of guessing a delay.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML="<p>Ready</p>"; });\ncy.contains("p", "Ready").should("be.visible");','The assertion waits for the visible Ready paragraph within its configured time limit.','Ask for missing text and read the timeout message.','Arbitrary cy.wait delays can make tests both slow and unreliable.','What should a test wait for?','A meaningful condition','A random delay'),
('Read a yielded value','then receives the value yielded by the previous command. This is how you inspect queued results.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML="<p>Moon</p>"; });\ncy.get("p").then($p => { expect($p.text()).to.equal("Moon"); });','The callback receives the paragraph and checks its text.','Read a different paragraph value.','Do not assign cy.get to a variable and treat it as the DOM element.','Where is the yielded paragraph available?','Inside then','As a plain return value immediately'),
('Work with checkboxes','check requests the checked state. It states intent more clearly than a toggle click.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML=\'<label><input id="remember" type="checkbox">Remember</label>\'; });\ncy.get("#remember").check().should("be.checked");','The box is checked.','Uncheck it and assert not.be.checked.','Check applies to checkboxes and radio buttons, not an arbitrary button.','Which action sets checked state?','check','clear'),
('Select a dropdown value','select chooses a native option by value or text. Assert the stored value after the action.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML=\'<select id="size"><option value="s">Small</option><option value="l">Large</option></select>\'; });\ncy.get("#size").select("l").should("have.value", "l");','The Large option is selected.','Select Small by its visible text.','A custom popup is not a native select and needs different actions.','What is the selected value?','l','s'),
('Count a collection','A query can find several elements. have.length checks how many the query found.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML="<ul><li>Moon</li><li>Ocean</li></ul>"; });\ncy.get("li").should("have.length", 2);','Two list items are found.','Add a third item.','A correct count does not guarantee correct item text.','How many items are checked?','2','1'),
('Intercept a request','intercept can supply a known network response. Set it up before the page sends the request.','cy.intercept("GET", "/books.json", { body: [{ title: "Moon" }] }).as("books");\ncy.visit("/practice.html");\ncy.window().then(win => win.fetch("/books.json"));\ncy.wait("@books").its("response.statusCode").should("eq", 200);','The intercepted request returns a test response with status 200. No book API service is required.','Use a response with an empty list.','A mocked response tests the frontend contract, not a real server implementation.','Who supplies the books response here?','The intercept rule','A required online database'),
('Keep tests independent','A test should set up the state it needs. Cypress test isolation helps avoid state leaking from a previous test.','cy.visit("/practice.html");\ncy.window().then(win => { win.localStorage.setItem("theme", "light"); });\ncy.window().its("localStorage").invoke("getItem", "theme").should("eq", "light");','This test arranges its own theme value.','Write a separate case that arranges dark.','Do not rely on one test running before another to prepare data.','Where should needed state be prepared?','In the test or its setup','Only in a previous test'),
('Review failures and screenshots','A failed assertion tells you which expected condition was not met. Use the command log and screenshot to understand it.','cy.visit("/practice.html");\ncy.document().then(doc => { doc.body.innerHTML="<h1>Library</h1>"; });\ncy.contains("h1", "Library").should("be.visible");\ncy.screenshot("library-page");','The test verifies the heading and records visible evidence.','Name a screenshot so another person can identify the page.','Do not hide a failure by deleting its assertion.','What should you do with a failed assertion?','Compare actual behaviour with the intended rule','Remove every check'),
]
records=[]
for title,idea,body,result,task,warning,q,a,w in cypress:
    records.append(L(title,idea,'describe("local practice", () => {\n  it("'+title.lower()+'", () => {\n'+ '\n'.join('    '+line for line in body.splitlines())+'\n  });\n});',result,task,warning,q,a,w,language='typescript'))
C('cypress','Cypress tests frontend behaviour in a browser. We will use a blank local practice page to learn queries, clicks, inputs and controlled network responses.','Use a local Cypress project. Set baseUrl to your local static frontend address and create a blank practice.html there. These test files do not run in this website\'s code sandbox.','https://docs.cypress.io/app/get-started/why-cypress',records)

selenium=[
('Open a small page','Selenium controls a browser through WebDriver. A data URL can hold a tiny HTML page for a local practice test.','<h1>Library</h1>','assert driver.find_element(By.TAG_NAME, "h1").text == "Library"','The check passes when the heading says Library.','Change the heading and expected text.','Close the driver in finally so a failed check does not leave a browser open.','What does WebDriver control?','A browser','A database server'),
('Find by ID','An ID should identify one page element. Selenium can use it to find a control.','<button id="save">Save</button>','assert driver.find_element(By.ID, "save").text == "Save"','The check reads the Save button.','Change the ID in both the page and locator.','Two elements should not share the same ID.','Which locator finds this button?','By.ID','By.FILE'),
('Find several elements','find_elements returns a list of all matches. It is different from find_element, which returns one match.','<ul><li>Moon</li><li>Ocean</li></ul>','assert len(driver.find_elements(By.TAG_NAME, "li")) == 2','The list has two matching elements.','Add a third list item.','An empty result list is different from a single element not being found.','Which call returns several matches?','find_elements','find_element'),
('Type into an input','send_keys types into an element. Read the value property to see what the field now contains.','<label for="title">Title</label><input id="title">','field = driver.find_element(By.ID, "title")\nfield.send_keys("Moon")\nassert field.get_property("value") == "Moon"','The input value becomes Moon.','Clear the input before typing Ocean.','Element text is not the same as an input\'s value property.','Where is the typed text stored?','The value property','The tag name'),
('Click and observe','A click asks the browser to activate a control. Check the resulting page state.','<button id="save" onclick="this.textContent=\'Done\'">Save</button>','driver.find_element(By.ID, "save").click()\nassert driver.find_element(By.ID, "save").text == "Done"','After the click, the button reads Done.','Change the action to write Saved.','A click alone does not prove the intended action completed.','What confirms the action?','The resulting Done text','The variable name driver'),
('Use a CSS selector','A CSS selector describes elements by tags, classes or attributes. Keep it short and tied to a clear target.','<p class="notice">Ready</p>','assert driver.find_element(By.CSS_SELECTOR, "p.notice").text == "Ready"','The selector chooses a paragraph with class notice.','Add an unrelated paragraph and keep the same locator.','Long position-based selectors can break after a harmless layout change.','What does p.notice select?','A paragraph with class notice','Every paragraph in every page'),
('Check selected state','A checkbox has a selected state that can be inspected. Clicking toggles that state.','<label><input id="remember" type="checkbox">Remember</label>','box = driver.find_element(By.ID, "remember")\nbox.click()\nassert box.is_selected()','The checkbox is selected after the click.','Click again and assert the state is false.','Check the starting state before using a toggle as a setup step.','Which method reads checkbox state?','is_selected','is_named'),
('Choose a select option','Selenium\'s Select helper handles a native select element. Choose an option by its stored value.','<select id="size"><option value="s">Small</option><option value="l">Large</option></select>','from selenium.webdriver.support.ui import Select\nmenu = Select(driver.find_element(By.ID, "size"))\nmenu.select_by_value("l")\nassert menu.first_selected_option.text == "Large"','The selected option is Large.','Choose s and check Small.','The Select helper does not work on a custom menu built from div elements.','What value selects Large?','l','s'),
('Wait for a condition','An explicit wait checks for a condition until a time limit. It is more useful than always sleeping a fixed length.','<p id="ready">Ready</p>','from selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\nitem = WebDriverWait(driver, 5).until(EC.visibility_of_element_located((By.ID, "ready")))\nassert item.text == "Ready"','The wait returns when the Ready element is visible, or fails after its limit.','Wait for a missing ID and read the failure.','Do not use long fixed sleeps to hide a timing problem.','What ends the wait successfully?','The requested condition becomes true','A random delay'),
('Press a keyboard key','Keyboard actions help check access beyond mouse clicks. Tab normally moves focus to the next control.','<input id="first"><input id="second">','from selenium.webdriver.common.keys import Keys\nfirst = driver.find_element(By.ID, "first")\nfirst.click()\nfirst.send_keys(Keys.TAB)\nassert driver.switch_to.active_element.get_attribute("id") == "second"','Focus moves to the second input.','Use Shift+Tab to go back.','A keyboard test should check the focused element, not just send a key.','Which key is used to move forward?','Tab','Escape'),
('Find an element again after change','A page can replace a DOM element. A saved old element reference may then be stale, so locate the current element again.','<button id="replace" onclick="document.getElementById(\'message\').outerHTML=\'<p id=message>New</p>\'">Replace</button><p id="message">Old</p>','driver.find_element(By.ID, "replace").click()\nassert driver.find_element(By.ID, "message").text == "New"','The fresh locator finds the replacement paragraph.','Describe why keeping the old paragraph reference could fail.','Do not retry the same stale object forever; find the current element.','What should you locate after replacement?','The new element','Only the old saved reference'),
('Save evidence and close','A screenshot helps show what the browser displayed. Always release browser resources when a test ends.','<h1>Library</h1>','assert driver.find_element(By.TAG_NAME, "h1").is_displayed()\ndriver.save_screenshot("library.png")','A screenshot is saved locally after the visibility check. The surrounding finally block closes the browser.','Choose a useful screenshot name for an error page.','A screenshot supplements assertions; it does not check every hidden rule.','What closes the browser in these examples?','driver.quit in finally','Saving a screenshot'),
]
records=[]
for title,idea,html,body,result,task,warning,q,a,w in selenium:
    code='from urllib.parse import quote\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\n\ndriver = webdriver.Chrome()\ntry:\n    driver.get("data:text/html;charset=utf-8," + quote('+repr(html)+'))\n'+'\n'.join('    '+line for line in body.splitlines())+'\nfinally:\n    driver.quit()'
    records.append(L(title,idea,code,result,task,warning,q,a,w,language='python'))
C('selenium','Selenium drives a browser so a test can use a page much like a person does. We will check tiny pages using Python, clear locators and explicit waits.','These examples need Python, Selenium and a compatible installed browser in a local test project. Selenium Manager may download a driver. They do not run in this website\'s playground.','https://www.selenium.dev/documentation/webdriver/',records)
